// Puts Castle in Android's Share menu.
//
// The Android project (src-tauri/gen/android) is generated by `tauri android init` and is
// not committed, so this runs after that step and before the build (.github/workflows/
// android.yml), and can be run by hand the same way:   node scripts/android-share.mjs
//
// It makes two changes, and making them twice changes nothing:
//   1. AndroidManifest.xml: the main activity accepts shared text (ACTION_SEND, text/plain),
//      which is what a browser or the YouTube app sends for "Share > Castle".
//   2. MainActivity.kt: what was shared is kept, and the interface collects it once through
//      window.CastleShare.take() (app/src/lib/share.js), then saves it in Links.
//
// Nothing shared is sent anywhere by this code: it goes to the interface, which sends it
// to the person's own box.

import { readFileSync, writeFileSync, readdirSync, statSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const MAIN = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', 'src-tauri', 'gen', 'android', 'app', 'src', 'main');
const MARK = 'CastleShare';

const FILTER = `
            <!-- ${MARK}: text shared from another app (a link) opens Castle, which saves it. -->
            <intent-filter>
                <action android:name="android.intent.action.SEND" />
                <category android:name="android.intent.category.DEFAULT" />
                <data android:mimeType="text/plain" />
            </intent-filter>`;

const IMPORTS = ['android.content.Intent', 'android.webkit.JavascriptInterface', 'android.webkit.WebView'];

const METHODS = `
  // ${MARK}: see app/scripts/android-share.mjs.
  override fun onNewIntent(intent: Intent) {
    super.onNewIntent(intent)
    setIntent(intent) // a share while Castle is already open
  }

  override fun onWebViewCreate(webView: WebView) {
    super.onWebViewCreate(webView)
    webView.addJavascriptInterface(${MARK}(this), "${MARK}")
  }
`;

const BRIDGE = `
/** What another app shared to Castle, handed to the interface once. */
class ${MARK}(private val activity: MainActivity) {
  @JavascriptInterface
  fun take(): String {
    val intent = activity.intent ?: return ""
    if (intent.action != Intent.ACTION_SEND) return ""
    val text = intent.getStringExtra(Intent.EXTRA_TEXT) ?: ""
    // Taken: turning the screen or coming back to the app must not save it again.
    intent.action = Intent.ACTION_MAIN
    intent.removeExtra(Intent.EXTRA_TEXT)
    return text
  }
}
`;

function fail(message) {
  console.error(`android-share: ${message}`);
  process.exit(1);
}

function find(dir, name) {
  for (const entry of readdirSync(dir)) {
    const full = path.join(dir, entry);
    if (statSync(full).isDirectory()) {
      const found = find(full, name);
      if (found) return found;
    } else if (entry === name) {
      return full;
    }
  }
  return null;
}

function patchManifest() {
  const file = path.join(MAIN, 'AndroidManifest.xml');
  const xml = readFileSync(file, 'utf8');
  if (xml.includes(MARK)) return 'already there';
  // After the launcher's own intent-filter, which is inside the main activity.
  const launcher = xml.indexOf('android.intent.category.LAUNCHER');
  const close = launcher < 0 ? -1 : xml.indexOf('</intent-filter>', launcher);
  if (close < 0) fail(`no launcher intent-filter in ${file}`);
  const at = close + '</intent-filter>'.length;
  writeFileSync(file, xml.slice(0, at) + FILTER + xml.slice(at));
  return 'added';
}

function patchActivity() {
  const file = find(path.join(MAIN, 'java'), 'MainActivity.kt');
  if (!file) fail('no MainActivity.kt in the Android project');
  let code = readFileSync(file, 'utf8');
  if (code.includes(MARK)) return 'already there';
  const declared = code.match(/class\s+MainActivity\s*:\s*TauriActivity\(\)/);
  if (!declared) fail(`MainActivity is not the shape this script knows: ${file}`);
  for (const override of ['onNewIntent', 'onWebViewCreate']) {
    if (code.includes(`fun ${override}`)) fail(`MainActivity already has ${override}; merge it by hand in ${file}`);
  }
  const afterName = declared.index + declared[0].length;
  const hasBody = /^\s*\{/.test(code.slice(afterName));
  if (hasBody) {
    const end = code.lastIndexOf('}');
    code = code.slice(0, end) + METHODS + code.slice(end);
  } else {
    code = `${code.slice(0, afterName)} {${METHODS}}${code.slice(afterName)}`;
  }
  const missing = IMPORTS.filter((name) => !code.includes(`import ${name}`)).map((name) => `import ${name}`).join('\n');
  const pkg = code.match(/^package .*$/m);
  if (!pkg) fail(`no package line in ${file}`);
  const afterPackage = pkg.index + pkg[0].length;
  code = `${code.slice(0, afterPackage)}\n\n${missing}${code.slice(afterPackage)}`;
  writeFileSync(file, `${code.trimEnd()}\n${BRIDGE}`);
  return 'added';
}

console.log(`android-share: manifest ${patchManifest()}, activity ${patchActivity()}`);
